#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 100
int top = -1;
int stack[MAX_SIZE];
void push(int value) {
    if (top < MAX_SIZE - 1) {
        stack[++top] = value;
    }
}
int pop() {
    if (top >= 0) {
        return stack[top--];
    }
    return -1;
}
int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <postfix_expression>\n", argv[0]);
        return 1;
    }
    for (int i = 1; i < argc; i++) {
        char *token = argv[i];
        if (token[0] == '+' || token[0] == '-' || token[0] == '*' || token[0] == '/') {
            int operand2 = pop();
            int operand1 = pop();
            if (operand1 == -1 || operand2 == -1) {
                printf("ERROR\n");
                return 1;
            }
            int result;
            switch (token[0]) {
                case '+':
                    result = operand1 + operand2;
                    break;
                case '-':
                    result = operand1 - operand2;
                    break;
                case '*':
                    result = operand1 * operand2;
                    break;
                case '/':
                    if (operand2 == 0) {
                        printf("ERROR\n");
                        return 1;
                    }
                    result = operand1 / operand2;
                    break;
            }
            push(result);
        } else {
            int value = atoi(token);
            push(value);
        }
    }
    if (top != 0) {
        printf("ERROR\n");
        return 1;
    }
    printf("%d\n", stack[0]);
    return 0;
}
